def _ensure_dirs_for(path):
    d = os.path.dirname(path)
    os.makedirs(d, exist_ok=True)

def _ensure_project_plugins(project_path):
    """Add required plugins to .uproject's Plugins array; remove deprecated ones."""
    import json as _json
    required = {"ProceduralMeshComponent", "EditorScriptingUtilities"}
    deprecated = {"Blutility"}
    try:
        with open(project_path, "r") as f:
            uproj = _json.load(f)
        plugins = uproj.get("Plugins", [])
        existing = {p.get("Name") for p in plugins}
        changed = False
        for name in required:
            if name not in existing:
                plugins.append({"Name": name, "Enabled": True})
                changed = True
        plugins = [p for p in plugins if p.get("Name") not in deprecated]
        if len(plugins) != len(uproj.get("Plugins", [])):
            changed = True
        if changed:
            uproj["Plugins"] = plugins
            with open(project_path, "w") as f:
                _json.dump(uproj, f, indent=4)
            unreal.log(f"[OK] Updated plugins in .uproject")
    except Exception as e:
        unreal.log_warning(f"[COMPILE] Could not update plugins in .uproject: {e}")

def _add_module_to_project(project_path, module_name):
    """Register module in .uproject so the engine loads it at startup.
    Uses PostDefault so all Default-phase plugin modules (e.g.
    ProceduralMeshComponent) finish UClass registration first."""
    import json as _json
    try:
        with open(project_path, "r") as f:
            uproj = _json.load(f)
        modules = uproj.get("Modules", [])
        for m in modules:
            if m.get("Name") == module_name:
                if m.get("LoadingPhase") != "PostDefault":
                    m["LoadingPhase"] = "PostDefault"
                    with open(project_path, "w") as f:
                        _json.dump(uproj, f, indent=4)
                    unreal.log(f"[OK] Updated '{module_name}' LoadingPhase to PostDefault")
                return
        modules.append({
            "Name": module_name,
            "Type": "Runtime",
            "LoadingPhase": "PostDefault",
        })
        uproj["Modules"] = modules
        with open(project_path, "w") as f:
            _json.dump(uproj, f, indent=4)
        unreal.log(f"[OK] Added module '{module_name}' with LoadingPhase=PostDefault")
    except Exception as e:
        unreal.log_warning(f"[COMPILE] Could not update .uproject: {e}")

def _patch_livecoding_json_full(json_path, module_name):
    """Read LiveCoding.json written by UBT, fill in ALL fields the
    UE5.8 LiveCoding parser requires (LinkerPath, module Inputs, etc.).
    Also reads LiveCodingModules.json for correct module structure."""
    import json as _json
    try:
        with open(json_path, "r") as f:
            data = _json.load(f)
    except Exception:
        return

    eng = os.path.dirname(os.path.dirname(json_path))
    changed = False

    # --- LinkerPath ---
    if "LinkerPath" not in data:
        link_path = os.path.join(
            eng, "Intermediate", "Build", "Win64",
            "UnrealEditor", "Development", "UnrealEditor.link")
        data["LinkerPath"] = link_path.replace("\\", "/")
        _ensure_dirs_for(link_path)
        if not os.path.exists(link_path):
            with open(link_path, "w") as _:
                pass
        changed = True

    # --- Modules — copy fields from LiveCodingModules.json if available,
    #     otherwise supply enough to pass parsing.
    lc_modules_path = os.path.join(
        os.path.dirname(json_path), "LiveCodingModules.json")
    ref_modules = {}
    try:
        with open(lc_modules_path, "r") as f:
            lc_data = _json.load(f)
        for m in lc_data.get("Modules", []):
            ref_modules[m.get("Name")] = m
    except Exception:
        pass

    if "Modules" not in data:
        data["Modules"] = []
        changed = True

    if not any(m.get("Name") == module_name for m in data["Modules"]):
        out_dll = os.path.join(
            eng, "Binaries", "Win64",
            f"{module_name}Editor-LiveCoding.dll").replace("\\", "/")
        entry = {"Name": module_name, "Output": out_dll}
        # Copy known-good fields from LiveCodingModules.json
        ref = ref_modules.get(module_name, {})
        for key in ("Inputs", "Dependencies", "ForceWeakRoots",
                     "PrecompiledModuleRequests", "LinkerObjects"):
            if key in ref:
                entry[key] = ref[key]
        # Supply defaults for required fields if still missing
        entry.setdefault("Inputs", [])
        entry.setdefault("Dependencies", [])
        entry.setdefault("ForceWeakRoots", False)
        data["Modules"].append(entry)
        changed = True

    if changed:
        with open(json_path, "w") as f:
            _json.dump(data, f, indent=4)
        unreal.log("[COMPILE] Patched LiveCoding.json with all required fields")


def compile_cpp_module():
    """Compile the C++ module so FaceParallax classes become available.
    Returns True if classes are available after compilation."""
    written = copy_cpp_sources()
    if written < 0:
        return False
    if written == 0 and class_available(PRESET_CLASS_NAME):
        unreal.log("[OK] C++ classes already available and sources unchanged")
        return True

    if written > 0:
        unreal.log(f"[COMPILE] {written} source file(s) updated — forcing recompilation")
    else:
        unreal.log("[COMPILE] C++ classes not found. Compiling...")

    project_path = unreal.Paths.get_project_file_path()
    if not project_path:
        unreal.log_warning("[MANUAL] Cannot resolve project path")
        return False

    module_name = os.path.splitext(os.path.basename(project_path))[0]

    # If no sources changed and the module is already compiled, load it directly
    if written == 0:
        for mod_name in [module_name, f"{module_name}Editor", f"{module_name}Editor-LiveCoding"]:
            try:
                world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
                if world:
                    unreal.SystemLibrary.execute_console_command(world, f"Module.Load {mod_name}")
                    time.sleep(1)
                    if class_available(PRESET_CLASS_NAME):
                        unreal.log(f"[OK] C++ classes available after loading '{mod_name}'")
                        return True
            except Exception:
                pass

    # Ensure .uproject has module entry + required plugins
    _add_module_to_project(project_path, module_name)
    _ensure_project_plugins(project_path)
    try:
        world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
        if world:
            unreal.SystemLibrary.execute_console_command(world,
                f"Project.AddModule {module_name} Development Default")
    except Exception:
        pass

    # Check if project DLL already exists
    project_dir = os.path.dirname(project_path)
    dll_path = os.path.join(project_dir, "Binaries", "Win64", f"UnrealEditor-{module_name}.dll")
    dll_exists = os.path.exists(dll_path)

    if dll_exists and written == 0:
        # DLL exists with no source changes — use LiveCoding.Compile for incremental changes
        engine_intermediate = os.path.join(unreal.Paths.engine_dir(), "Intermediate")
        lc_json_path = os.path.join(engine_intermediate, "LiveCoding.json")
        lc_last_mtime = 0
        try:
            world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
            if world:
                unreal.log("[COMPILE] DLL exists — using LiveCoding.Compile")
                unreal.SystemLibrary.execute_console_command(world, "LiveCoding.Compile")
                unreal.log("[COMPILE] Waiting up to 10 minutes for build...")
                for _ in range(600):
                    time.sleep(1)
                    if class_available(PRESET_CLASS_NAME):
                        unreal.log("[OK] C++ classes available after LiveCoding.Compile")
                        return True
                    if os.path.exists(lc_json_path):
                        mtime = os.path.getmtime(lc_json_path)
                        if mtime > lc_last_mtime:
                            lc_last_mtime = mtime
                            _patch_livecoding_json_full(lc_json_path, module_name)
                unreal.log("[COMPILE] LiveCoding.Compile did not finish in 10 min")
        except Exception as e:
            unreal.log(f"[COMPILE] LiveCoding.Compile failed: {e}")
        # LiveCoding failed — try loading existing module
    elif dll_exists and written > 0:
        unreal.log("[COMPILE] DLL exists with source changes — trying Module.Load...")
        for mod_name in [module_name, f"{module_name}Editor", f"{module_name}Editor-LiveCoding"]:
            try:
                world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
                if world:
                    unreal.SystemLibrary.execute_console_command(world, f"Module.Load {mod_name}")
                    time.sleep(1)
                    if class_available(PRESET_CLASS_NAME):
                        unreal.log(f"[OK] C++ classes available after loading '{mod_name}'")
                        return True
            except Exception:
                pass
        unreal.log("[MANUAL] Module.Load did not expose classes.\n"
                   "   If you built from Visual Studio / UBT, run deploy again (sources are now up to date).\n"
                   f"   Open {module_name}.sln and build '{module_name}Editor' (Development Editor).")
        return False
    else:
        unreal.log("[MANUAL] Project DLL not found.\n"
                   "   Build from Visual Studio once to create the initial DLL, then run deploy again.\n"
                   f"   Open {module_name}.sln and build '{module_name}Editor' (Development Editor).")
        return False

    # Module.Load after LiveCoding — registers classes if hot-reload didn't
    for mod_name in [module_name, f"{module_name}Editor", f"{module_name}Editor-LiveCoding"]:
        try:
            world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
            if world:
                unreal.SystemLibrary.execute_console_command(world, f"Module.Load {mod_name}")
                time.sleep(2)
                if class_available(PRESET_CLASS_NAME):
                    unreal.log(f"[OK] C++ classes available after Module.Load {mod_name}")
                    return True
        except Exception:
            pass

    # One more check if LiveCoding applied but Module.Load wasn't needed
    if class_available(PRESET_CLASS_NAME):
        return True

    unreal.log_warning(
        "[MANUAL] LiveCoding.Compile applied but classes not yet available.\n"
        "   Wait a moment or restart the editor and run deploy.py again."
    )
    return False


# --------------------------------------------------------------
# 1. Master Material
# --------------------------------------------------------------
def create_master_material():
    mat_path = f"{CONTENT_ROOT}/Materials"
    ensure_dir(mat_path)

    mat_name = "M_FaceParallax_Master"
    full_path = f"{mat_path}/{mat_name}"

    # Untextured albedo samples fall back to UE's built-in 1x1 white
    # DefaultTexture automatically, so face-layer quads stay visible before
    # any art is imported
    if editor_asset_lib.does_asset_exist(full_path):
        unreal.log(f"[SKIP] {full_path} already exists")
        return unreal.load_asset(full_path)

    factory = unreal.MaterialFactoryNew()
    material = asset_tools.create_asset(mat_name, mat_path, unreal.Material, factory)

    mel = unreal.MaterialEditingLibrary

    def tex_param(name, x, y):
        node = mel.create_material_expression(material, unreal.MaterialExpressionTextureSampleParameter2D, x, y)
        node.set_editor_property("parameter_name", name)
        return node

    def scalar_param(name, x, y, default=0.0):
        node = mel.create_material_expression(material, unreal.MaterialExpressionScalarParameter, x, y)
        node.set_editor_property("parameter_name", name)
        node.set_editor_property("default_value", default)
        return node

    def vec_param(name, x, y):
        node = mel.create_material_expression(material, unreal.MaterialExpressionVectorParameter, x, y)
        node.set_editor_property("parameter_name", name)
        return node

    def static_switch(name, x, y, default=False):
        node = mel.create_material_expression(material, unreal.MaterialExpressionStaticBoolParameter, x, y)
        node.set_editor_property("parameter_name", name)
        node.set_editor_property("default_value", default)
        return node

    # --- Parameters (mirrors the checklist's parameter list) ---
    albedo_cur   = tex_param("AlbedoTexture",     -600, -300)
    albedo_prev  = tex_param("AlbedoTexturePrev",  -600, -150)
    normal_cur   = tex_param("NormalTexture",      -600,    0)
    normal_prev  = tex_param("NormalTexturePrev",  -600,  150)
    depth_cur    = tex_param("DepthTexture",       -600,  300)
    depth_prev   = tex_param("DepthTexturePrev",   -600,  450)

    blend_alpha  = scalar_param("StateBlendAlpha", -600, 600, 0.0)
    parallax_off = vec_param("ParallaxOffset",     -600, 750)
    art_pos      = vec_param("ArtPosition",         -600, 900)
    art_scale    = vec_param("ArtScale",             -600, 1050)
    art_rot      = scalar_param("ArtRotation",       -600, 1200, 0.0)
    depth_int    = scalar_param("DepthIntensity",    -600, 1350, 1.0)
    debug_depth  = static_switch("DebugDepth",       -600, 1500, False)
    is_topdown   = static_switch("IsTopDown",        -600, 1650, False)
    is_topview   = static_switch("IsTopView",        -600, 1800, False)

    art_pivot    = vec_param("ArtPivot",              -600, 1950)
    nested_frame = scalar_param("NestedAnimFrame",    -600, 2100, 0.0)

    expr_alpha   = scalar_param("ExpressionBlendAlpha", -600, 2250, 0.0)
    expr_alb_prev = tex_param("ExpressionAlbedoPrev",  -600, 2400)
    expr_nrm_prev = tex_param("ExpressionNormalPrev",  -600, 2550)
    expr_dep_prev = tex_param("ExpressionDepthPrev",   -600, 2700)

    # --- UV: pan by ParallaxOffset scaled with ArtPosition/ArtScale ---
    texcoord = mel.create_material_expression(material, unreal.MaterialExpressionTextureCoordinate, -1000, -300)
    uv_add_pos = mel.create_material_expression(material, unreal.MaterialExpressionAdd, -850, -300)
    mel.connect_material_expressions(texcoord, "", uv_add_pos, "A")
    mel.connect_material_expressions(art_pos, "", uv_add_pos, "B")

    uv_mul_scale = mel.create_material_expression(material, unreal.MaterialExpressionMultiply, -750, -300)
    mel.connect_material_expressions(uv_add_pos, "", uv_mul_scale, "A")
    mel.connect_material_expressions(art_scale, "", uv_mul_scale, "B")

    uv_final = mel.create_material_expression(material, unreal.MaterialExpressionAdd, -680, -280)
    mel.connect_material_expressions(uv_mul_scale, "", uv_final, "A")
    mel.connect_material_expressions(parallax_off, "", uv_final, "B")

    for tex_node in (albedo_cur, albedo_prev, normal_cur, normal_prev, depth_cur, depth_prev):
        mel.connect_material_expressions(uv_final, "", tex_node, "UVs")

    # --- Crossfade current/prev per channel via StateBlendAlpha ---
    def lerp(a, b, alpha, x, y):
        node = mel.create_material_expression(material, unreal.MaterialExpressionLinearInterpolate, x, y)
        mel.connect_material_expressions(a, "", node, "A")
        mel.connect_material_expressions(b, "", node, "B")
        mel.connect_material_expressions(alpha, "", node, "Alpha")
        return node

    albedo_blend = lerp(albedo_prev, albedo_cur, blend_alpha, -300, -250)
    normal_blend = lerp(normal_prev, normal_cur, blend_alpha, -300, 50)
    depth_blend  = lerp(depth_prev, depth_cur, blend_alpha, -300, 350)

    depth_scaled = mel.create_material_expression(material, unreal.MaterialExpressionMultiply, -150, 350)
    mel.connect_material_expressions(depth_blend, "", depth_scaled, "A")
    mel.connect_material_expressions(depth_int, "", depth_scaled, "B")

    # DebugDepth switch: show raw depth in place of albedo when enabled
    debug_switch = mel.create_material_expression(material, unreal.MaterialExpressionStaticSwitch, 50, -100)
    mel.connect_material_expressions(debug_depth, "", debug_switch, "Value")
    mel.connect_material_expressions(depth_scaled, "", debug_switch, "True")
    mel.connect_material_expressions(albedo_blend, "", debug_switch, "False")

    mel.connect_material_property(debug_switch, unreal.MaterialProperty.MP_BASE_COLOR, 0)
    mel.connect_material_property(normal_blend, unreal.MaterialProperty.MP_NORMAL, 0)

    mel.recompile_material(material)
    editor_asset_lib.save_asset(full_path)
    unreal.log(f"[OK] Created {full_path} with wired parameter graph")
    return material


