def main():
    unreal.log("==> Deploying FaceParallax editor assets")
    ensure_dir(CONTENT_ROOT)

    # Phase 1: No C++ classes needed
    master_mat = create_master_material()
    create_material_instances(master_mat)

    # Phase 2: Compile if needed
    if not compile_cpp_module():
        return

    # Phase 3: C++ classes available
    preset = create_preset_asset()
    create_character_blueprint(preset)
    widget_bp = create_editor_widget_blueprint()

    # Phase 4: Render target + preview actor
    rt = create_render_target()
    preview_actor = spawn_preview_actor(preset, rt)

    # Phase 5: Populate widget layout
    if widget_bp and preview_actor:
        populate_widget_layout(widget_bp, preview_actor, rt)

    # Phase 6: Register toolbar
    register_editor_toolbar()

    unreal.log(f"==> Done. The FaceParallax editor tool is ready.")
    unreal.log(f"   - C++ module compiled with all 221 UFUNCTIONs")
    unreal.log(f"   - Character BP: {CHARACTER_OUTPUT_PATH}/{CHARACTER_BP_NAME}")
    unreal.log(f"   - Editor Widget: {EDITOR_UTILITY_WIDGET_PATH.split('.')[0]}")
    unreal.log(f"   - Render Target: {CONTENT_ROOT}/Textures/RT_FaceParallaxPreview")
    unreal.log(f"   - Preview Actor spawned in editor world")
    unreal.log(f"   - Type 'FaceParallaxOpenEditor' in the console to open the interactive editor")
    unreal.log("[HINT] Live Coding patches do NOT survive an editor restart. If you restart the editor,")
    unreal.log("[HINT] run deploy.py again to recompile, then open the editor from the Face Editor")
    unreal.log("[HINT] toolbar button or 'FaceParallaxOpenEditor' console command. It must open as a")
    unreal.log("[HINT] DOCKED TAB in the main editor window — if you get a separate floating window,")
    unreal.log("[HINT] the old C++ module is still loaded (check the log for '[FaceParallax] EditorSubsystem")
    unreal.log("[HINT] initialized — DOCKED-TAB BUILD v3').")


if __name__ == "__main__":
    main()
